-- =============================================================================
-- Gestión Pro · V1: esquema base
-- Oracle Database 21c XE / 23ai Free. Ejecutado por Flyway.
--
-- Convenciones
--   * Tablas y columnas en español, snake_case.
--   * PK: id NUMBER GENERATED BY DEFAULT AS IDENTITY.
--   * Booleanos: NUMBER(1) con CHECK (0,1) (compatible con 21c).
--   * Montos en pesos: NUMBER(14,2). Porcentajes: NUMBER(5,2) entre 0 y 100.
--   * Duraciones en días hábiles según el calendario del proyecto.
--   * Estados derivados (actividad atrasada, hito atrasado, semáforo actual)
--     NO se guardan: se calculan. Así no pueden quedar desincronizados.
--   * Módulo 2 (EDT) fuera de alcance: la jerarquía etapa → actividad →
--     subactividad vive en ACTIVIDAD.padre_id, sin códigos EDT ni consolidación.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Seguridad
-- -----------------------------------------------------------------------------
CREATE TABLE usuario (
  id            NUMBER GENERATED BY DEFAULT AS IDENTITY,
  nombre        VARCHAR2(120) NOT NULL,
  correo        VARCHAR2(160) NOT NULL,
  clave_hash    VARCHAR2(100) NOT NULL,          -- BCrypt
  rol           VARCHAR2(20)  NOT NULL,
  activo        NUMBER(1) DEFAULT 1 NOT NULL,
  creado_en     TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_usuario PRIMARY KEY (id),
  CONSTRAINT uk_usuario_correo UNIQUE (correo),
  CONSTRAINT ck_usuario_rol CHECK (rol IN ('ADMINISTRADOR', 'USUARIO_PROYECTO')),
  CONSTRAINT ck_usuario_activo CHECK (activo IN (0, 1)),
  CONSTRAINT ck_usuario_correo CHECK (correo = LOWER(correo) AND INSTR(correo, '@') > 1)
);

-- -----------------------------------------------------------------------------
-- Calendario laboral
-- -----------------------------------------------------------------------------
CREATE TABLE calendario (
  id            NUMBER GENERATED BY DEFAULT AS IDENTITY,
  nombre        VARCHAR2(80) NOT NULL,
  lunes         NUMBER(1) DEFAULT 1 NOT NULL,
  martes        NUMBER(1) DEFAULT 1 NOT NULL,
  miercoles     NUMBER(1) DEFAULT 1 NOT NULL,
  jueves        NUMBER(1) DEFAULT 1 NOT NULL,
  viernes       NUMBER(1) DEFAULT 1 NOT NULL,
  sabado        NUMBER(1) DEFAULT 0 NOT NULL,
  domingo       NUMBER(1) DEFAULT 0 NOT NULL,
  horas_dia     NUMBER(4,2) DEFAULT 8 NOT NULL,
  CONSTRAINT pk_calendario PRIMARY KEY (id),
  CONSTRAINT ck_calendario_dias CHECK (
    lunes IN (0,1) AND martes IN (0,1) AND miercoles IN (0,1) AND jueves IN (0,1)
    AND viernes IN (0,1) AND sabado IN (0,1) AND domingo IN (0,1)
    AND lunes + martes + miercoles + jueves + viernes + sabado + domingo > 0),
  CONSTRAINT ck_calendario_horas CHECK (horas_dia > 0 AND horas_dia <= 24)
);

CREATE TABLE dia_no_laborable (
  id            NUMBER GENERATED BY DEFAULT AS IDENTITY,
  calendario_id NUMBER NOT NULL,
  fecha         DATE NOT NULL,
  motivo        VARCHAR2(120) NOT NULL,
  CONSTRAINT pk_dia_no_laborable PRIMARY KEY (id),
  CONSTRAINT fk_dnl_calendario FOREIGN KEY (calendario_id) REFERENCES calendario (id) ON DELETE CASCADE,
  CONSTRAINT uk_dnl_fecha UNIQUE (calendario_id, fecha),
  CONSTRAINT ck_dnl_fecha CHECK (fecha = TRUNC(fecha))
);

-- -----------------------------------------------------------------------------
-- Módulo 1 · Proyectos
-- -----------------------------------------------------------------------------
CREATE TABLE proyecto (
  id                  NUMBER GENERATED BY DEFAULT AS IDENTITY,
  codigo              VARCHAR2(20)  NOT NULL,
  nombre              VARCHAR2(150) NOT NULL,
  descripcion         VARCHAR2(2000),
  responsable_id      NUMBER NOT NULL,
  calendario_id       NUMBER NOT NULL,
  fecha_inicio_plan   DATE NOT NULL,
  fecha_termino_plan  DATE NOT NULL,
  fecha_inicio_real   DATE,
  fecha_termino_real  DATE,
  presupuesto         NUMBER(14,2) NOT NULL,
  estado              VARCHAR2(20) DEFAULT 'PLANIFICADO' NOT NULL,
  avance              NUMBER(5,2) DEFAULT 0 NOT NULL,   -- lo recalcula el backend
  version             NUMBER DEFAULT 0 NOT NULL,        -- bloqueo optimista (JPA @Version)
  CONSTRAINT pk_proyecto PRIMARY KEY (id),
  CONSTRAINT uk_proyecto_codigo UNIQUE (codigo),
  CONSTRAINT fk_proyecto_responsable FOREIGN KEY (responsable_id) REFERENCES usuario (id),
  CONSTRAINT fk_proyecto_calendario FOREIGN KEY (calendario_id) REFERENCES calendario (id),
  CONSTRAINT ck_proyecto_estado CHECK (estado IN ('PLANIFICADO', 'EN_EJECUCION', 'SUSPENDIDO', 'TERMINADO')),
  CONSTRAINT ck_proyecto_fechas CHECK (fecha_termino_plan >= fecha_inicio_plan),
  CONSTRAINT ck_proyecto_fechas_real CHECK (fecha_termino_real IS NULL OR fecha_inicio_real IS NULL OR fecha_termino_real >= fecha_inicio_real),
  CONSTRAINT ck_proyecto_presupuesto CHECK (presupuesto >= 0),
  CONSTRAINT ck_proyecto_avance CHECK (avance BETWEEN 0 AND 100),
  CONSTRAINT ck_proyecto_terminado CHECK (estado <> 'TERMINADO' OR fecha_termino_real IS NOT NULL)
);
CREATE INDEX ix_proyecto_responsable ON proyecto (responsable_id);

-- Usuarios de proyecto que pueden ver y editar un proyecto
CREATE TABLE proyecto_miembro (
  proyecto_id   NUMBER NOT NULL,
  usuario_id    NUMBER NOT NULL,
  CONSTRAINT pk_proyecto_miembro PRIMARY KEY (proyecto_id, usuario_id),
  CONSTRAINT fk_pm_proyecto FOREIGN KEY (proyecto_id) REFERENCES proyecto (id) ON DELETE CASCADE,
  CONSTRAINT fk_pm_usuario FOREIGN KEY (usuario_id) REFERENCES usuario (id) ON DELETE CASCADE
);

-- -----------------------------------------------------------------------------
-- Módulo 5 · Catálogo de profesionales (compartido entre proyectos para
-- detectar sobreasignación semanal aunque trabajen en más de un proyecto)
-- -----------------------------------------------------------------------------
CREATE TABLE tipo_profesional (
  id                NUMBER GENERATED BY DEFAULT AS IDENTITY,
  categoria         VARCHAR2(80) NOT NULL,
  tarifa_hora_ref   NUMBER(12,2) NOT NULL,
  CONSTRAINT pk_tipo_profesional PRIMARY KEY (id),
  CONSTRAINT uk_tipo_profesional UNIQUE (categoria),
  CONSTRAINT ck_tp_tarifa CHECK (tarifa_hora_ref > 0)
);

CREATE TABLE profesional (
  id                    NUMBER GENERATED BY DEFAULT AS IDENTITY,
  nombre                VARCHAR2(120) NOT NULL,
  especialidad          VARCHAR2(80)  NOT NULL,
  tipo_profesional_id   NUMBER NOT NULL,
  valor_hora            NUMBER(12,2) NOT NULL,
  horas_semana_disp     NUMBER(5,2) DEFAULT 40 NOT NULL,
  usuario_id            NUMBER,                       -- si además usa el sistema
  activo                NUMBER(1) DEFAULT 1 NOT NULL,
  CONSTRAINT pk_profesional PRIMARY KEY (id),
  CONSTRAINT fk_prof_tipo FOREIGN KEY (tipo_profesional_id) REFERENCES tipo_profesional (id),
  CONSTRAINT fk_prof_usuario FOREIGN KEY (usuario_id) REFERENCES usuario (id),
  CONSTRAINT uk_prof_usuario UNIQUE (usuario_id),
  CONSTRAINT ck_prof_valor CHECK (valor_hora > 0),
  CONSTRAINT ck_prof_horas CHECK (horas_semana_disp > 0 AND horas_semana_disp <= 168),
  CONSTRAINT ck_prof_activo CHECK (activo IN (0, 1))
);

-- Dotación requerida por categoría en cada proyecto ("tipo de profesional")
CREATE TABLE requerimiento_profesional (
  id                    NUMBER GENERATED BY DEFAULT AS IDENTITY,
  proyecto_id           NUMBER NOT NULL,
  tipo_profesional_id   NUMBER NOT NULL,
  cantidad_requerida    NUMBER(3) NOT NULL,
  tarifa_hora           NUMBER(12,2) NOT NULL,
  CONSTRAINT pk_requerimiento_profesional PRIMARY KEY (id),
  CONSTRAINT fk_rp_proyecto FOREIGN KEY (proyecto_id) REFERENCES proyecto (id) ON DELETE CASCADE,
  CONSTRAINT fk_rp_tipo FOREIGN KEY (tipo_profesional_id) REFERENCES tipo_profesional (id),
  CONSTRAINT uk_rp UNIQUE (proyecto_id, tipo_profesional_id),
  CONSTRAINT ck_rp_cantidad CHECK (cantidad_requerida > 0),
  CONSTRAINT ck_rp_tarifa CHECK (tarifa_hora > 0)
);

-- -----------------------------------------------------------------------------
-- Módulo 3 · Actividades y dependencias
-- -----------------------------------------------------------------------------
CREATE TABLE actividad (
  id                  NUMBER GENERATED BY DEFAULT AS IDENTITY,
  proyecto_id         NUMBER NOT NULL,
  padre_id            NUMBER,
  tipo                VARCHAR2(15) NOT NULL,
  orden               NUMBER(5) DEFAULT 0 NOT NULL,      -- posición entre hermanos
  nombre              VARCHAR2(150) NOT NULL,
  descripcion         VARCHAR2(2000),
  responsable_id      NUMBER,
  duracion_plan       NUMBER(5) NOT NULL,                -- días hábiles
  duracion_real       NUMBER(5),
  fecha_inicio_plan   DATE,                              -- la calcula el motor de programación
  fecha_termino_plan  DATE,
  fecha_inicio_real   DATE,
  fecha_termino_real  DATE,
  avance              NUMBER(5,2) DEFAULT 0 NOT NULL,
  version             NUMBER DEFAULT 0 NOT NULL,
  CONSTRAINT pk_actividad PRIMARY KEY (id),
  -- clave compuesta para que DEPENDENCIA y ACTIVIDAD.padre_id no crucen proyectos
  CONSTRAINT uk_actividad_proyecto UNIQUE (id, proyecto_id),
  CONSTRAINT fk_act_proyecto FOREIGN KEY (proyecto_id) REFERENCES proyecto (id) ON DELETE CASCADE,
  CONSTRAINT fk_act_padre FOREIGN KEY (padre_id, proyecto_id) REFERENCES actividad (id, proyecto_id) ON DELETE CASCADE,
  CONSTRAINT fk_act_responsable FOREIGN KEY (responsable_id) REFERENCES profesional (id),
  CONSTRAINT ck_act_tipo CHECK (tipo IN ('ETAPA', 'ACTIVIDAD', 'SUBACTIVIDAD')),
  -- las etapas cuelgan del proyecto; el resto siempre tiene padre
  CONSTRAINT ck_act_padre CHECK ((tipo = 'ETAPA' AND padre_id IS NULL) OR (tipo <> 'ETAPA' AND padre_id IS NOT NULL)),
  CONSTRAINT ck_act_no_self CHECK (padre_id IS NULL OR padre_id <> id),
  CONSTRAINT ck_act_duracion CHECK (duracion_plan >= 0 AND (duracion_real IS NULL OR duracion_real >= 0)),
  CONSTRAINT ck_act_fechas CHECK (fecha_termino_plan IS NULL OR fecha_inicio_plan IS NULL OR fecha_termino_plan >= fecha_inicio_plan),
  CONSTRAINT ck_act_fechas_real CHECK (fecha_termino_real IS NULL OR fecha_inicio_real IS NULL OR fecha_termino_real >= fecha_inicio_real),
  CONSTRAINT ck_act_termino_real CHECK (fecha_termino_real IS NULL OR fecha_inicio_real IS NOT NULL),
  CONSTRAINT ck_act_avance CHECK (avance BETWEEN 0 AND 100),
  CONSTRAINT ck_act_avance_100 CHECK (avance < 100 OR fecha_termino_real IS NOT NULL)
);
CREATE INDEX ix_actividad_proyecto ON actividad (proyecto_id, padre_id, orden);
CREATE INDEX ix_actividad_responsable ON actividad (responsable_id);

-- Relación de precedencia. Los ciclos se rechazan en el backend (orden topológico).
CREATE TABLE dependencia (
  id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
  proyecto_id     NUMBER NOT NULL,
  predecesora_id  NUMBER NOT NULL,
  sucesora_id     NUMBER NOT NULL,
  tipo            CHAR(2) NOT NULL,
  desfase_dias    NUMBER(5) DEFAULT 0 NOT NULL,    -- positivo o negativo, días hábiles
  CONSTRAINT pk_dependencia PRIMARY KEY (id),
  CONSTRAINT fk_dep_predecesora FOREIGN KEY (predecesora_id, proyecto_id) REFERENCES actividad (id, proyecto_id) ON DELETE CASCADE,
  CONSTRAINT fk_dep_sucesora FOREIGN KEY (sucesora_id, proyecto_id) REFERENCES actividad (id, proyecto_id) ON DELETE CASCADE,
  CONSTRAINT uk_dep_par UNIQUE (predecesora_id, sucesora_id),
  CONSTRAINT ck_dep_tipo CHECK (tipo IN ('FS', 'SS', 'FF', 'SF')),
  CONSTRAINT ck_dep_no_self CHECK (predecesora_id <> sucesora_id)
);
CREATE INDEX ix_dep_sucesora ON dependencia (sucesora_id);
CREATE INDEX ix_dep_proyecto ON dependencia (proyecto_id);

-- -----------------------------------------------------------------------------
-- Módulo 5 · Recursos no humanos y asignaciones (con costos)
-- -----------------------------------------------------------------------------
CREATE TABLE recurso (
  id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
  proyecto_id     NUMBER NOT NULL,
  tipo            VARCHAR2(15) NOT NULL,
  descripcion     VARCHAR2(150) NOT NULL,     -- software, material, equipo u otro
  detalle         VARCHAR2(150),              -- tipo de licencia, modalidad de arriendo, etc.
  unidad          VARCHAR2(30),               -- unidad, rollo, mes, jornada…
  cantidad        NUMBER(10,2) NOT NULL,
  costo_unitario  NUMBER(14,2) NOT NULL,
  periodo         NUMBER(4) DEFAULT 1 NOT NULL,  -- meses de licencia o arriendo; 1 si no aplica
  costo_total     NUMBER(16,2) GENERATED ALWAYS AS (cantidad * costo_unitario * periodo) VIRTUAL,
  CONSTRAINT pk_recurso PRIMARY KEY (id),
  CONSTRAINT uk_recurso_proyecto UNIQUE (id, proyecto_id),
  CONSTRAINT fk_recurso_proyecto FOREIGN KEY (proyecto_id) REFERENCES proyecto (id) ON DELETE CASCADE,
  CONSTRAINT ck_recurso_tipo CHECK (tipo IN ('LICENCIA', 'MATERIAL', 'EQUIPAMIENTO', 'OTRO')),
  CONSTRAINT ck_recurso_cantidad CHECK (cantidad > 0),
  CONSTRAINT ck_recurso_costo CHECK (costo_unitario >= 0),
  CONSTRAINT ck_recurso_periodo CHECK (periodo >= 1)
);

-- costo profesional = horas semanales × semanas × valor hora (columna virtual)
CREATE TABLE asignacion_profesional (
  id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
  actividad_id    NUMBER NOT NULL,
  profesional_id  NUMBER NOT NULL,
  horas_semana    NUMBER(5,2) NOT NULL,
  semanas         NUMBER(5,2) NOT NULL,
  valor_hora      NUMBER(12,2) NOT NULL,     -- copia al asignar: un alza posterior no cambia lo planificado
  costo_plan      NUMBER(16,2) GENERATED ALWAYS AS (horas_semana * semanas * valor_hora) VIRTUAL,
  horas_reales    NUMBER(8,2) DEFAULT 0 NOT NULL,
  costo_real      NUMBER(16,2) DEFAULT 0 NOT NULL,
  CONSTRAINT pk_asignacion_profesional PRIMARY KEY (id),
  CONSTRAINT fk_ap_actividad FOREIGN KEY (actividad_id) REFERENCES actividad (id) ON DELETE CASCADE,
  CONSTRAINT fk_ap_profesional FOREIGN KEY (profesional_id) REFERENCES profesional (id),
  CONSTRAINT uk_ap UNIQUE (actividad_id, profesional_id),
  CONSTRAINT ck_ap_horas CHECK (horas_semana > 0 AND horas_semana <= 168),
  CONSTRAINT ck_ap_semanas CHECK (semanas > 0),
  CONSTRAINT ck_ap_valor CHECK (valor_hora > 0),
  CONSTRAINT ck_ap_real CHECK (horas_reales >= 0 AND costo_real >= 0)
);
CREATE INDEX ix_ap_profesional ON asignacion_profesional (profesional_id);

-- costo material = cantidad × valor unitario × periodo (columna virtual)
CREATE TABLE asignacion_recurso (
  id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
  actividad_id    NUMBER NOT NULL,
  recurso_id      NUMBER NOT NULL,
  cantidad        NUMBER(10,2) NOT NULL,
  costo_unitario  NUMBER(14,2) NOT NULL,     -- copia del recurso al asignar
  periodo         NUMBER(4) DEFAULT 1 NOT NULL,
  costo_plan      NUMBER(16,2) GENERATED ALWAYS AS (cantidad * costo_unitario * periodo) VIRTUAL,
  costo_real      NUMBER(16,2) DEFAULT 0 NOT NULL,
  CONSTRAINT pk_asignacion_recurso PRIMARY KEY (id),
  CONSTRAINT fk_ar_actividad FOREIGN KEY (actividad_id) REFERENCES actividad (id) ON DELETE CASCADE,
  CONSTRAINT fk_ar_recurso FOREIGN KEY (recurso_id) REFERENCES recurso (id),
  CONSTRAINT uk_ar UNIQUE (actividad_id, recurso_id),
  CONSTRAINT ck_ar_cantidad CHECK (cantidad > 0),
  CONSTRAINT ck_ar_costo CHECK (costo_unitario >= 0 AND costo_real >= 0),
  CONSTRAINT ck_ar_periodo CHECK (periodo >= 1)
);
CREATE INDEX ix_ar_recurso ON asignacion_recurso (recurso_id);

-- -----------------------------------------------------------------------------
-- Módulo 6 · Hitos
-- -----------------------------------------------------------------------------
CREATE TABLE hito (
  id                    NUMBER GENERATED BY DEFAULT AS IDENTITY,
  proyecto_id           NUMBER NOT NULL,
  codigo                VARCHAR2(10) NOT NULL,          -- H1, H2…
  descripcion           VARCHAR2(200) NOT NULL,
  responsable_id        NUMBER NOT NULL,
  fecha_comprometida    DATE NOT NULL,
  fecha_real            DATE,
  estado                VARCHAR2(15) DEFAULT 'PENDIENTE' NOT NULL,  -- "atrasado" se calcula
  CONSTRAINT pk_hito PRIMARY KEY (id),
  CONSTRAINT uk_hito_proyecto UNIQUE (id, proyecto_id),
  CONSTRAINT uk_hito_codigo UNIQUE (proyecto_id, codigo),
  CONSTRAINT fk_hito_proyecto FOREIGN KEY (proyecto_id) REFERENCES proyecto (id) ON DELETE CASCADE,
  CONSTRAINT fk_hito_responsable FOREIGN KEY (responsable_id) REFERENCES profesional (id),
  CONSTRAINT ck_hito_estado CHECK (estado IN ('PENDIENTE', 'CUMPLIDO', 'CANCELADO')),
  CONSTRAINT ck_hito_cumplido CHECK ((estado = 'CUMPLIDO' AND fecha_real IS NOT NULL) OR (estado <> 'CUMPLIDO' AND fecha_real IS NULL))
);

-- Un hito se asocia a una o más actividades del mismo proyecto
CREATE TABLE hito_actividad (
  hito_id       NUMBER NOT NULL,
  actividad_id  NUMBER NOT NULL,
  proyecto_id   NUMBER NOT NULL,
  CONSTRAINT pk_hito_actividad PRIMARY KEY (hito_id, actividad_id),
  CONSTRAINT fk_ha_hito FOREIGN KEY (hito_id, proyecto_id) REFERENCES hito (id, proyecto_id) ON DELETE CASCADE,
  CONSTRAINT fk_ha_actividad FOREIGN KEY (actividad_id, proyecto_id) REFERENCES actividad (id, proyecto_id) ON DELETE CASCADE
);
CREATE INDEX ix_ha_actividad ON hito_actividad (actividad_id);

CREATE TABLE hito_criterio (
  id            NUMBER GENERATED BY DEFAULT AS IDENTITY,
  hito_id       NUMBER NOT NULL,
  orden         NUMBER(3) DEFAULT 1 NOT NULL,
  descripcion   VARCHAR2(300) NOT NULL,
  cumplido      NUMBER(1) DEFAULT 0 NOT NULL,
  CONSTRAINT pk_hito_criterio PRIMARY KEY (id),
  CONSTRAINT fk_hc_hito FOREIGN KEY (hito_id) REFERENCES hito (id) ON DELETE CASCADE,
  CONSTRAINT ck_hc_cumplido CHECK (cumplido IN (0, 1))
);
CREATE INDEX ix_hc_hito ON hito_criterio (hito_id);

-- -----------------------------------------------------------------------------
-- Módulo 8 · Gestión del cambio
-- -----------------------------------------------------------------------------
-- Las diez etapas del flujo son datos (V2), no código: se ajustan si el profesor
-- define otras sin tocar el esquema.
CREATE TABLE etapa_cambio (
  numero        NUMBER(2) NOT NULL,
  nombre        VARCHAR2(60) NOT NULL,
  descripcion   VARCHAR2(300),
  CONSTRAINT pk_etapa_cambio PRIMARY KEY (numero),
  CONSTRAINT ck_ec_numero CHECK (numero BETWEEN 1 AND 10)
);

CREATE TABLE solicitud_cambio (
  id                  NUMBER GENERATED BY DEFAULT AS IDENTITY,
  proyecto_id         NUMBER NOT NULL,
  codigo              VARCHAR2(10) NOT NULL,           -- SC-001
  solicitante         VARCHAR2(120) NOT NULL,
  fecha_solicitud     DATE DEFAULT TRUNC(SYSDATE) NOT NULL,
  descripcion         VARCHAR2(2000) NOT NULL,
  justificacion       VARCHAR2(2000) NOT NULL,
  tipo                VARCHAR2(15) NOT NULL,
  prioridad           VARCHAR2(10) NOT NULL,
  -- riesgo e impacto
  riesgo              VARCHAR2(1000),
  probabilidad        VARCHAR2(5),
  impacto             VARCHAR2(5),
  impacto_plazo_dias  NUMBER(5) DEFAULT 0 NOT NULL,
  impacto_costo       NUMBER(14,2) DEFAULT 0 NOT NULL,
  impacto_recursos    VARCHAR2(300),
  impacto_alcance     VARCHAR2(300),
  -- gestión
  responsable_id      NUMBER NOT NULL,
  estado              VARCHAR2(20) DEFAULT 'ABIERTO' NOT NULL,
  etapa_actual        NUMBER(2) DEFAULT 1 NOT NULL,
  fecha_comprometida  DATE NOT NULL,
  fecha_real          DATE,
  costo_estimado      NUMBER(14,2) DEFAULT 0 NOT NULL,
  costo_real          NUMBER(14,2),
  aprobado_por_id     NUMBER,
  fecha_decision      TIMESTAMP,
  resultado           VARCHAR2(2000),
  efectividad         NUMBER(5,2),                     -- % evaluado al cierre
  adopcion            NUMBER(5,2),                     -- % medido tras implementar
  version             NUMBER DEFAULT 0 NOT NULL,
  CONSTRAINT pk_solicitud_cambio PRIMARY KEY (id),
  CONSTRAINT uk_sc_codigo UNIQUE (proyecto_id, codigo),
  CONSTRAINT fk_sc_proyecto FOREIGN KEY (proyecto_id) REFERENCES proyecto (id) ON DELETE CASCADE,
  CONSTRAINT fk_sc_responsable FOREIGN KEY (responsable_id) REFERENCES usuario (id),
  CONSTRAINT fk_sc_aprobador FOREIGN KEY (aprobado_por_id) REFERENCES usuario (id),
  CONSTRAINT fk_sc_etapa FOREIGN KEY (etapa_actual) REFERENCES etapa_cambio (numero),
  CONSTRAINT ck_sc_tipo CHECK (tipo IN ('ALCANCE', 'TIEMPO', 'COSTO', 'RECURSO', 'TECNOLOGIA', 'ORGANIZACION')),
  CONSTRAINT ck_sc_prioridad CHECK (prioridad IN ('BAJA', 'MEDIA', 'ALTA', 'CRITICA')),
  CONSTRAINT ck_sc_probabilidad CHECK (probabilidad IS NULL OR probabilidad IN ('BAJA', 'MEDIA', 'ALTA')),
  CONSTRAINT ck_sc_impacto CHECK (impacto IS NULL OR impacto IN ('BAJO', 'MEDIO', 'ALTO')),
  CONSTRAINT ck_sc_estado CHECK (estado IN ('ABIERTO', 'EN_EVALUACION', 'APROBADO', 'RECHAZADO', 'EN_IMPLEMENTACION', 'CERRADO')),
  CONSTRAINT ck_sc_fechas CHECK (fecha_comprometida >= fecha_solicitud),
  CONSTRAINT ck_sc_costos CHECK (costo_estimado >= 0 AND (costo_real IS NULL OR costo_real >= 0)),
  CONSTRAINT ck_sc_porcentajes CHECK ((efectividad IS NULL OR efectividad BETWEEN 0 AND 100) AND (adopcion IS NULL OR adopcion BETWEEN 0 AND 100)),
  -- aprobar o rechazar exige quién y cuándo
  CONSTRAINT ck_sc_decision CHECK (estado IN ('ABIERTO', 'EN_EVALUACION') OR (aprobado_por_id IS NOT NULL AND fecha_decision IS NOT NULL)),
  -- cerrar exige fecha real y resultado
  CONSTRAINT ck_sc_cierre CHECK (estado <> 'CERRADO' OR (fecha_real IS NOT NULL AND resultado IS NOT NULL))
);
CREATE INDEX ix_sc_estado ON solicitud_cambio (proyecto_id, estado);

-- Seguimiento de cada una de las diez etapas por solicitud
CREATE TABLE solicitud_etapa (
  id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
  solicitud_id    NUMBER NOT NULL,
  etapa_numero    NUMBER(2) NOT NULL,
  estado          VARCHAR2(12) DEFAULT 'PENDIENTE' NOT NULL,
  responsable_id  NUMBER,
  fecha_inicio    DATE,
  fecha_fin       DATE,
  fecha_limite    DATE,
  observacion     VARCHAR2(1000),
  CONSTRAINT pk_solicitud_etapa PRIMARY KEY (id),
  CONSTRAINT uk_se UNIQUE (solicitud_id, etapa_numero),
  CONSTRAINT fk_se_solicitud FOREIGN KEY (solicitud_id) REFERENCES solicitud_cambio (id) ON DELETE CASCADE,
  CONSTRAINT fk_se_etapa FOREIGN KEY (etapa_numero) REFERENCES etapa_cambio (numero),
  CONSTRAINT fk_se_responsable FOREIGN KEY (responsable_id) REFERENCES usuario (id),
  CONSTRAINT ck_se_estado CHECK (estado IN ('PENDIENTE', 'EN_CURSO', 'COMPLETADA', 'OMITIDA')),
  CONSTRAINT ck_se_fechas CHECK (fecha_fin IS NULL OR fecha_inicio IS NULL OR fecha_fin >= fecha_inicio),
  CONSTRAINT ck_se_completada CHECK (estado <> 'COMPLETADA' OR fecha_fin IS NOT NULL)
);

-- Trazabilidad: qué cambió cada solicitud aprobada (valor anterior → nuevo)
CREATE TABLE cambio_modificacion (
  id                NUMBER GENERATED BY DEFAULT AS IDENTITY,
  solicitud_id      NUMBER NOT NULL,
  entidad           VARCHAR2(25) NOT NULL,
  entidad_id        NUMBER NOT NULL,
  campo             VARCHAR2(40) NOT NULL,
  valor_anterior    VARCHAR2(200),
  valor_nuevo       VARCHAR2(200) NOT NULL,
  aplicada          NUMBER(1) DEFAULT 0 NOT NULL,
  fecha_aplicacion  TIMESTAMP,
  CONSTRAINT pk_cambio_modificacion PRIMARY KEY (id),
  CONSTRAINT fk_cm_solicitud FOREIGN KEY (solicitud_id) REFERENCES solicitud_cambio (id) ON DELETE CASCADE,
  CONSTRAINT ck_cm_entidad CHECK (entidad IN ('ACTIVIDAD', 'DEPENDENCIA', 'ASIGNACION_PROFESIONAL', 'ASIGNACION_RECURSO', 'RECURSO', 'HITO', 'PROYECTO')),
  CONSTRAINT ck_cm_aplicada CHECK ((aplicada = 0 AND fecha_aplicacion IS NULL) OR (aplicada = 1 AND fecha_aplicacion IS NOT NULL))
);
CREATE INDEX ix_cm_entidad ON cambio_modificacion (entidad, entidad_id);
CREATE INDEX ix_cm_solicitud ON cambio_modificacion (solicitud_id);

CREATE TABLE accion_correctiva (
  id                NUMBER GENERATED BY DEFAULT AS IDENTITY,
  solicitud_id      NUMBER NOT NULL,
  descripcion       VARCHAR2(500) NOT NULL,
  responsable_id    NUMBER NOT NULL,
  fecha_compromiso  DATE NOT NULL,
  fecha_cierre      DATE,
  estado            VARCHAR2(10) DEFAULT 'ABIERTA' NOT NULL,
  CONSTRAINT pk_accion_correctiva PRIMARY KEY (id),
  CONSTRAINT fk_ac_solicitud FOREIGN KEY (solicitud_id) REFERENCES solicitud_cambio (id) ON DELETE CASCADE,
  CONSTRAINT fk_ac_responsable FOREIGN KEY (responsable_id) REFERENCES usuario (id),
  CONSTRAINT ck_ac_estado CHECK (estado IN ('ABIERTA', 'CERRADA')),
  CONSTRAINT ck_ac_cierre CHECK ((estado = 'CERRADA' AND fecha_cierre IS NOT NULL) OR (estado = 'ABIERTA' AND fecha_cierre IS NULL))
);
CREATE INDEX ix_ac_solicitud ON accion_correctiva (solicitud_id);

-- Línea base: copia de fechas y costos antes de aplicar un cambio aprobado
CREATE TABLE linea_base (
  id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
  proyecto_id     NUMBER NOT NULL,
  numero          NUMBER(3) NOT NULL,          -- LB-01, LB-02…
  solicitud_id    NUMBER,                      -- nulo para la línea base inicial
  creada_en       TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  creada_por_id   NUMBER NOT NULL,
  fecha_termino   DATE NOT NULL,
  costo_total     NUMBER(16,2) NOT NULL,
  CONSTRAINT pk_linea_base PRIMARY KEY (id),
  CONSTRAINT uk_lb_numero UNIQUE (proyecto_id, numero),
  CONSTRAINT uk_lb_solicitud UNIQUE (solicitud_id),
  CONSTRAINT fk_lb_proyecto FOREIGN KEY (proyecto_id) REFERENCES proyecto (id) ON DELETE CASCADE,
  CONSTRAINT fk_lb_solicitud FOREIGN KEY (solicitud_id) REFERENCES solicitud_cambio (id),
  CONSTRAINT fk_lb_usuario FOREIGN KEY (creada_por_id) REFERENCES usuario (id)
);

CREATE TABLE linea_base_actividad (
  linea_base_id       NUMBER NOT NULL,
  actividad_id        NUMBER NOT NULL,
  fecha_inicio_plan   DATE NOT NULL,
  fecha_termino_plan  DATE NOT NULL,
  duracion_plan       NUMBER(5) NOT NULL,
  costo_plan          NUMBER(16,2) NOT NULL,
  CONSTRAINT pk_linea_base_actividad PRIMARY KEY (linea_base_id, actividad_id),
  CONSTRAINT fk_lba_lb FOREIGN KEY (linea_base_id) REFERENCES linea_base (id) ON DELETE CASCADE,
  CONSTRAINT fk_lba_actividad FOREIGN KEY (actividad_id) REFERENCES actividad (id) ON DELETE CASCADE
);

-- Evidencias de hitos y de solicitudes (el archivo se guarda en la base para la demo local)
CREATE TABLE evidencia (
  id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
  hito_id         NUMBER,
  solicitud_id    NUMBER,
  nombre_archivo  VARCHAR2(200) NOT NULL,
  tipo_mime       VARCHAR2(100) NOT NULL,
  tamano_bytes    NUMBER(12) NOT NULL,
  contenido       BLOB NOT NULL,
  subido_por_id   NUMBER NOT NULL,
  subido_en       TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_evidencia PRIMARY KEY (id),
  CONSTRAINT fk_ev_hito FOREIGN KEY (hito_id) REFERENCES hito (id) ON DELETE CASCADE,
  CONSTRAINT fk_ev_solicitud FOREIGN KEY (solicitud_id) REFERENCES solicitud_cambio (id) ON DELETE CASCADE,
  CONSTRAINT fk_ev_usuario FOREIGN KEY (subido_por_id) REFERENCES usuario (id),
  -- pertenece exactamente a un hito o a una solicitud
  CONSTRAINT ck_ev_duenio CHECK ((hito_id IS NOT NULL AND solicitud_id IS NULL) OR (hito_id IS NULL AND solicitud_id IS NOT NULL)),
  CONSTRAINT ck_ev_tamano CHECK (tamano_bytes > 0 AND tamano_bytes <= 10485760)   -- 10 MB
);
CREATE INDEX ix_ev_hito ON evidencia (hito_id);
CREATE INDEX ix_ev_solicitud ON evidencia (solicitud_id);

-- -----------------------------------------------------------------------------
-- Módulos 7 y 9 · KPI configurables
-- -----------------------------------------------------------------------------
-- Variables que el backend sabe calcular; una fórmula solo puede usar estas.
CREATE TABLE variable_kpi (
  codigo        VARCHAR2(60) NOT NULL,
  descripcion   VARCHAR2(300) NOT NULL,
  unidad        VARCHAR2(20) NOT NULL,
  categoria     VARCHAR2(10) NOT NULL,
  CONSTRAINT pk_variable_kpi PRIMARY KEY (codigo),
  CONSTRAINT ck_vk_codigo CHECK (REGEXP_LIKE(codigo, '^[a-z][a-z0-9_]*$')),
  CONSTRAINT ck_vk_categoria CHECK (categoria IN ('PROYECTO', 'CAMBIO'))
);

-- Semáforo: verde si el valor cae en [verde_min, verde_max]; si no, ámbar si cae en
-- [ambar_min, ambar_max]; si no, rojo. Un límite nulo significa "sin límite".
-- Sirve igual para "mayor es mejor", "menor es mejor" y "rango".
CREATE TABLE kpi (
  id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
  proyecto_id     NUMBER NOT NULL,
  codigo          VARCHAR2(10) NOT NULL,          -- KP-01, KC-01
  nombre          VARCHAR2(120) NOT NULL,
  objetivo        VARCHAR2(500) NOT NULL,
  categoria       VARCHAR2(10) NOT NULL,          -- PROYECTO (incluye hitos) o CAMBIO
  ambito          VARCHAR2(10) NOT NULL,
  ambito_ref_id   NUMBER,                         -- etapa, actividad, hito o solicitud concreta
  formula         VARCHAR2(1000),                 -- nula si la fuente es manual
  unidad          VARCHAR2(20) NOT NULL,
  sentido         VARCHAR2(6) NOT NULL,
  meta            NUMBER(14,4) NOT NULL,
  verde_min       NUMBER(14,4),
  verde_max       NUMBER(14,4),
  ambar_min       NUMBER(14,4),
  ambar_max       NUMBER(14,4),
  periodicidad    VARCHAR2(10) NOT NULL,
  fuente          VARCHAR2(10) NOT NULL,
  responsable_id  NUMBER NOT NULL,
  activo          NUMBER(1) DEFAULT 1 NOT NULL,
  CONSTRAINT pk_kpi PRIMARY KEY (id),
  CONSTRAINT uk_kpi_codigo UNIQUE (proyecto_id, codigo),
  CONSTRAINT fk_kpi_proyecto FOREIGN KEY (proyecto_id) REFERENCES proyecto (id) ON DELETE CASCADE,
  CONSTRAINT fk_kpi_responsable FOREIGN KEY (responsable_id) REFERENCES usuario (id),
  CONSTRAINT ck_kpi_categoria CHECK (categoria IN ('PROYECTO', 'CAMBIO')),
  CONSTRAINT ck_kpi_ambito CHECK (ambito IN ('PROYECTO', 'ETAPA', 'ACTIVIDAD', 'HITO', 'CAMBIO')),
  CONSTRAINT ck_kpi_sentido CHECK (sentido IN ('MAYOR', 'MENOR', 'RANGO')),
  CONSTRAINT ck_kpi_periodicidad CHECK (periodicidad IN ('DIARIA', 'SEMANAL', 'QUINCENAL', 'MENSUAL', 'AL_EVENTO')),
  CONSTRAINT ck_kpi_fuente CHECK (fuente IN ('AUTOMATICA', 'MANUAL')),
  CONSTRAINT ck_kpi_formula CHECK (fuente = 'MANUAL' OR formula IS NOT NULL),
  CONSTRAINT ck_kpi_umbral_verde CHECK (verde_min IS NOT NULL OR verde_max IS NOT NULL),
  CONSTRAINT ck_kpi_rango_verde CHECK (verde_min IS NULL OR verde_max IS NULL OR verde_min <= verde_max),
  CONSTRAINT ck_kpi_rango_ambar CHECK (ambar_min IS NULL OR ambar_max IS NULL OR ambar_min <= ambar_max),
  CONSTRAINT ck_kpi_activo CHECK (activo IN (0, 1))
);

-- Variables usadas por cada fórmula (el backend la parsea al guardar y llena esta tabla)
CREATE TABLE kpi_variable (
  kpi_id          NUMBER NOT NULL,
  variable_codigo VARCHAR2(60) NOT NULL,
  CONSTRAINT pk_kpi_variable PRIMARY KEY (kpi_id, variable_codigo),
  CONSTRAINT fk_kv_kpi FOREIGN KEY (kpi_id) REFERENCES kpi (id) ON DELETE CASCADE,
  CONSTRAINT fk_kv_variable FOREIGN KEY (variable_codigo) REFERENCES variable_kpi (codigo)
);

-- Un hito tiene uno o varios KPI asociados
CREATE TABLE kpi_hito (
  kpi_id    NUMBER NOT NULL,
  hito_id   NUMBER NOT NULL,
  CONSTRAINT pk_kpi_hito PRIMARY KEY (kpi_id, hito_id),
  CONSTRAINT fk_kh_kpi FOREIGN KEY (kpi_id) REFERENCES kpi (id) ON DELETE CASCADE,
  CONSTRAINT fk_kh_hito FOREIGN KEY (hito_id) REFERENCES hito (id) ON DELETE CASCADE
);
CREATE INDEX ix_kh_hito ON kpi_hito (hito_id);

-- Histórico: cada recálculo o ingreso manual agrega una fila
CREATE TABLE medicion_kpi (
  id                NUMBER GENERATED BY DEFAULT AS IDENTITY,
  kpi_id            NUMBER NOT NULL,
  medido_en         TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  valor             NUMBER(14,4) NOT NULL,
  semaforo          VARCHAR2(5) NOT NULL,
  origen            VARCHAR2(10) NOT NULL,
  solicitud_id      NUMBER,                 -- si la medición la gatilló un cambio aprobado
  registrado_por_id NUMBER,                 -- obligatorio si es manual
  observacion       VARCHAR2(500),
  CONSTRAINT pk_medicion_kpi PRIMARY KEY (id),
  CONSTRAINT fk_mk_kpi FOREIGN KEY (kpi_id) REFERENCES kpi (id) ON DELETE CASCADE,
  CONSTRAINT fk_mk_solicitud FOREIGN KEY (solicitud_id) REFERENCES solicitud_cambio (id) ON DELETE SET NULL,
  CONSTRAINT fk_mk_usuario FOREIGN KEY (registrado_por_id) REFERENCES usuario (id),
  CONSTRAINT ck_mk_semaforo CHECK (semaforo IN ('VERDE', 'AMBAR', 'ROJO')),
  CONSTRAINT ck_mk_origen CHECK (origen IN ('RECALCULO', 'PROGRAMADA', 'MANUAL')),
  CONSTRAINT ck_mk_manual CHECK (origen <> 'MANUAL' OR registrado_por_id IS NOT NULL)
);
CREATE INDEX ix_mk_kpi_fecha ON medicion_kpi (kpi_id, medido_en DESC);

-- -----------------------------------------------------------------------------
-- Alertas (sobreasignación, KPI fuera de meta, atrasos, riesgos críticos…)
-- -----------------------------------------------------------------------------
CREATE TABLE alerta (
  id            NUMBER GENERATED BY DEFAULT AS IDENTITY,
  proyecto_id   NUMBER NOT NULL,
  tipo          VARCHAR2(25) NOT NULL,
  severidad     VARCHAR2(5) NOT NULL,
  mensaje       VARCHAR2(500) NOT NULL,
  entidad       VARCHAR2(25),
  entidad_id    NUMBER,
  creada_en     TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  resuelta      NUMBER(1) DEFAULT 0 NOT NULL,
  resuelta_en   TIMESTAMP,
  CONSTRAINT pk_alerta PRIMARY KEY (id),
  CONSTRAINT fk_alerta_proyecto FOREIGN KEY (proyecto_id) REFERENCES proyecto (id) ON DELETE CASCADE,
  CONSTRAINT ck_alerta_tipo CHECK (tipo IN ('SOBREASIGNACION', 'KPI_FUERA_META', 'ACTIVIDAD_ATRASADA', 'HITO_ATRASADO',
                                            'CAMBIO_ATRASADO', 'RIESGO_CRITICO', 'DESVIACION_COSTO')),
  CONSTRAINT ck_alerta_severidad CHECK (severidad IN ('ALTA', 'MEDIA')),
  CONSTRAINT ck_alerta_resuelta CHECK ((resuelta = 0 AND resuelta_en IS NULL) OR (resuelta = 1 AND resuelta_en IS NOT NULL))
);
CREATE INDEX ix_alerta_abiertas ON alerta (proyecto_id, resuelta, creada_en DESC);

-- -----------------------------------------------------------------------------
-- Reglas que no se expresan con CHECK
-- -----------------------------------------------------------------------------
-- Recursos solo en elementos hoja: si una actividad con hijos tuviera recursos,
-- su costo se sumaría dos veces (en ella y en sus subactividades).
CREATE OR REPLACE TRIGGER trg_ap_solo_hoja
BEFORE INSERT OR UPDATE OF actividad_id ON asignacion_profesional
FOR EACH ROW
DECLARE
  v_hijos NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_hijos FROM actividad WHERE padre_id = :NEW.actividad_id;
  IF v_hijos > 0 THEN
    RAISE_APPLICATION_ERROR(-20001, 'Solo se pueden asignar profesionales a actividades sin subactividades.');
  END IF;
END;
/

CREATE OR REPLACE TRIGGER trg_ar_solo_hoja
BEFORE INSERT OR UPDATE OF actividad_id ON asignacion_recurso
FOR EACH ROW
DECLARE
  v_hijos NUMBER;
  v_proy_act NUMBER;
  v_proy_rec NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_hijos FROM actividad WHERE padre_id = :NEW.actividad_id;
  IF v_hijos > 0 THEN
    RAISE_APPLICATION_ERROR(-20002, 'Solo se pueden asignar recursos a actividades sin subactividades.');
  END IF;
  SELECT proyecto_id INTO v_proy_act FROM actividad WHERE id = :NEW.actividad_id;
  SELECT proyecto_id INTO v_proy_rec FROM recurso WHERE id = :NEW.recurso_id;
  IF v_proy_act <> v_proy_rec THEN
    RAISE_APPLICATION_ERROR(-20003, 'El recurso y la actividad deben pertenecer al mismo proyecto.');
  END IF;
END;
/

-- Una actividad con recursos asignados no puede pasar a tener hijos.
CREATE OR REPLACE TRIGGER trg_act_padre_sin_recursos
BEFORE INSERT OR UPDATE OF padre_id ON actividad
FOR EACH ROW
WHEN (NEW.padre_id IS NOT NULL)
DECLARE
  v_asig NUMBER;
BEGIN
  SELECT (SELECT COUNT(*) FROM asignacion_profesional WHERE actividad_id = :NEW.padre_id)
       + (SELECT COUNT(*) FROM asignacion_recurso WHERE actividad_id = :NEW.padre_id)
    INTO v_asig FROM dual;
  IF v_asig > 0 THEN
    RAISE_APPLICATION_ERROR(-20004, 'La actividad padre tiene recursos asignados; quítalos antes de agregarle subactividades.');
  END IF;
END;
/

-- -----------------------------------------------------------------------------
-- Vistas de cálculo (las consume el backend y los tableros)
-- -----------------------------------------------------------------------------
-- costo de actividad = suma de costos de recursos asociados
CREATE OR REPLACE VIEW v_costo_actividad AS
SELECT a.id AS actividad_id,
       a.proyecto_id,
       NVL(p.plan, 0) + NVL(r.plan, 0) AS costo_plan,
       NVL(p.real, 0) + NVL(r.real, 0) AS costo_real
  FROM actividad a
  LEFT JOIN (SELECT actividad_id, SUM(costo_plan) plan, SUM(costo_real) real
               FROM asignacion_profesional GROUP BY actividad_id) p ON p.actividad_id = a.id
  LEFT JOIN (SELECT actividad_id, SUM(costo_plan) plan, SUM(costo_real) real
               FROM asignacion_recurso GROUP BY actividad_id) r ON r.actividad_id = a.id;

-- Costo consolidado por etapa (suma de sus descendientes; los recursos solo están en hojas)
CREATE OR REPLACE VIEW v_costo_etapa AS
SELECT raiz.id AS etapa_id,
       raiz.proyecto_id,
       SUM(c.costo_plan) AS costo_plan,
       SUM(c.costo_real) AS costo_real
  FROM actividad raiz
  JOIN (SELECT CONNECT_BY_ROOT id AS raiz_id, id
          FROM actividad
         START WITH tipo = 'ETAPA'
       CONNECT BY PRIOR id = padre_id) arbol ON arbol.raiz_id = raiz.id
  JOIN v_costo_actividad c ON c.actividad_id = arbol.id
 WHERE raiz.tipo = 'ETAPA'
 GROUP BY raiz.id, raiz.proyecto_id;

CREATE OR REPLACE VIEW v_costo_proyecto AS
SELECT pr.id AS proyecto_id,
       pr.presupuesto,
       NVL(SUM(c.costo_plan), 0) AS costo_plan,
       NVL(SUM(c.costo_real), 0) AS costo_real
  FROM proyecto pr
  LEFT JOIN v_costo_actividad c ON c.proyecto_id = pr.id
 GROUP BY pr.id, pr.presupuesto;

-- Estado derivado de hitos: atrasado = pendiente con fecha comprometida vencida
CREATE OR REPLACE VIEW v_hito_estado AS
SELECT h.*,
       CASE
         WHEN h.estado = 'PENDIENTE' AND h.fecha_comprometida < TRUNC(SYSDATE) THEN 'ATRASADO'
         ELSE h.estado
       END AS estado_calculado,
       CASE WHEN h.estado = 'CUMPLIDO' AND h.fecha_real <= h.fecha_comprometida THEN 1 ELSE 0 END AS cumplido_en_plazo
  FROM hito h;

-- Última medición de cada KPI (semáforo actual)
CREATE OR REPLACE VIEW v_kpi_actual AS
SELECT k.id AS kpi_id, k.proyecto_id, k.codigo, k.nombre, k.categoria, k.meta, k.unidad,
       m.valor, m.semaforo, m.medido_en
  FROM kpi k
  LEFT JOIN (SELECT kpi_id, valor, semaforo, medido_en,
                    ROW_NUMBER() OVER (PARTITION BY kpi_id ORDER BY medido_en DESC, id DESC) rn
               FROM medicion_kpi) m ON m.kpi_id = k.id AND m.rn = 1
 WHERE k.activo = 1;
